'use client';

import * as React from 'react';
import { Dialog as DialogPrimitive } from '@base-ui/react/dialog';
import { AnimatePresence, useIsPresent, usePresence } from 'motion/react';

import { getStrictContext } from '../../../utils/strict-context';
import {
  ReducedMotionConfig,
  useShouldReduceMotion,
} from '../../../utils/motion';
import {
  getAnimateTarget,
  useEnterAfterPaint,
  getContentTargets,
  getModalSide,
  motionRender,
  useBackdropFade,
  useOverlayTransitions,
  useHiddenWhenClosed,
  useContentTransitions,
  type ContentFlipProps,
  type ModalAnimationProps,
  type ModalTargets,
} from '../../../internal/modal-motion';

type OpenState = { open: boolean };

const [OpenProvider, useOpen] = getStrictContext<OpenState>('Dialog.Root');
const PortalContext = React.createContext<{ keepMounted: boolean }>({
  keepMounted: false,
});

type RootLikeProps = {
  open?: boolean;
  defaultOpen?: boolean;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  onOpenChange?: (open: boolean, eventDetails: any) => void;
};

function createRoot<Props extends RootLikeProps>(
  RootPrimitive: React.ComponentType<Props>,
) {
  return function Root({ defaultOpen, ...props }: Props) {
    const controlled = props.open !== undefined;
    const [uncontrolled, setUncontrolled] = React.useState(
      defaultOpen ?? false,
    );
    const open = controlled ? Boolean(props.open) : uncontrolled;

    const onOpenChange: RootLikeProps['onOpenChange'] = (next, details) => {
      props.onOpenChange?.(next, details);
      if ((details as { isCanceled?: boolean } | undefined)?.isCanceled) return;
      if (!controlled) setUncontrolled(next);
    };

    return (
      <OpenProvider value={{ open }}>
        <RootPrimitive
          {...(props as Props)}
          open={open}
          onOpenChange={onOpenChange}
        />
      </OpenProvider>
    );
  };
}

type PortalProps = DialogPrimitive.Portal.Props;

function Portal({ keepMounted, children, ...props }: PortalProps) {
  const { open } = useOpen();

  return (
    <AnimatePresence>
      {(open || keepMounted) && (
        <DialogPrimitive.Portal key="portal" {...props} keepMounted>
          <PortalContext value={{ keepMounted: Boolean(keepMounted) }}>
            <ReducedMotionConfig>{children}</ReducedMotionConfig>
          </PortalContext>
        </DialogPrimitive.Portal>
      )}
    </AnimatePresence>
  );
}

function useMotionElementProps(targets: ModalTargets) {
  const { open } = useOpen();
  const { keepMounted } = React.use(PortalContext);
  const isPresent = useIsPresent();
  const { hidden, onAnimationComplete } = useHiddenWhenClosed(
    open,
    keepMounted,
  );
  const exiting = !isPresent || (keepMounted && !open && !hidden);
  const entered = useEnterAfterPaint();

  return {
    initial: targets.initial,
    animate: entered
      ? getAnimateTarget(targets, open, keepMounted)
      : targets.initial,
    exit: targets.exit,
    onAnimationComplete,
    ...(exiting ? { hidden: false } : {}),
    ...(open ? {} : { style: { pointerEvents: 'none' as const } }),
  };
}

type BackdropProps = DialogPrimitive.Backdrop.Props & ModalAnimationProps;

function Backdrop({
  transition,
  exitTransition,
  render,
  ...props
}: BackdropProps) {
  const { open } = useOpen();
  const { keepMounted } = React.use(PortalContext);
  const [isPresent, safeToRemove] = usePresence();
  const { hidden, onAnimationComplete } = useHiddenWhenClosed(
    open,
    keepMounted,
  );
  const ref = useBackdropFade({
    visible: open && isPresent,
    ...useOverlayTransitions(transition, exitTransition),
    onFadedOut: () => {
      onAnimationComplete();
      safeToRemove?.();
    },
  });
  const exiting = !isPresent || (keepMounted && !open && !hidden);

  return (
    <DialogPrimitive.Backdrop
      {...props}
      render={motionRender(render, {
        ref,
        ...(exiting ? { hidden: false } : {}),
        ...(open ? {} : { style: { pointerEvents: 'none' as const } }),
      })}
    />
  );
}

type PopupProps = DialogPrimitive.Popup.Props &
  ModalAnimationProps &
  ContentFlipProps;

function Popup({
  from,
  transition,
  exitTransition,
  render,
  ...props
}: PopupProps) {
  const reduce = useShouldReduceMotion();
  const side = getModalSide((props as Record<string, unknown>)['data-side']);
  const { enter, exit } = useContentTransitions(
    side,
    transition,
    exitTransition,
  );
  const motionProps = useMotionElementProps(
    getContentTargets({ side, from, reduce, enter, exit }),
  );

  return (
    <DialogPrimitive.Popup
      {...props}
      render={motionRender(render, motionProps)}
    />
  );
}

export {
  createRoot,
  Portal,
  Backdrop,
  Popup,
  type PortalProps,
  type BackdropProps,
  type PopupProps,
};

'use client';

/* eslint-disable @typescript-eslint/no-namespace */

import { Dialog as DialogPrimitive } from '@base-ui/react/dialog';

import {
  Backdrop as AnimatedBackdrop,
  Popup as AnimatedPopup,
  Portal as AnimatedPortal,
  createRoot,
} from './base-modal';
import type {
  FlipDirection,
  ModalAnimationProps,
} from '../../../internal/modal-motion';

type BackdropAnimationProps = {
  transition?: ModalAnimationProps['transition'];
  exitTransition?: ModalAnimationProps['transition'];
};

type DialogFlipDirection = FlipDirection;

type PopupAnimationProps = {
  from?: DialogFlipDirection;
  transition?: ModalAnimationProps['transition'];
  exitTransition?: ModalAnimationProps['transition'];
};

const AnimatedRoot = createRoot(DialogPrimitive.Root);

function Root<Payload>(props: Root.Props<Payload>) {
  return <AnimatedRoot {...(props as DialogPrimitive.Root.Props)} />;
}
namespace Root {
  export type State = DialogPrimitive.Root.State;
  export type Props<Payload = unknown> = DialogPrimitive.Root.Props<Payload>;
  export type Actions = DialogPrimitive.Root.Actions;
  export type ChangeEventReason = DialogPrimitive.Root.ChangeEventReason;
  export type ChangeEventDetails = DialogPrimitive.Root.ChangeEventDetails;
}

function Portal(props: Portal.Props) {
  return <AnimatedPortal {...props} />;
}
namespace Portal {
  export type State = DialogPrimitive.Portal.State;
  export type Props = DialogPrimitive.Portal.Props;
}

function Backdrop(props: Backdrop.Props) {
  return <AnimatedBackdrop {...props} />;
}
namespace Backdrop {
  export type Props = DialogPrimitive.Backdrop.Props & BackdropAnimationProps;
  export type State = DialogPrimitive.Backdrop.State;
}

function Popup(props: Popup.Props) {
  return <AnimatedPopup {...props} />;
}
namespace Popup {
  export type Props = DialogPrimitive.Popup.Props & PopupAnimationProps;
  export type State = DialogPrimitive.Popup.State;
}

const Trigger = DialogPrimitive.Trigger;
namespace Trigger {
  export type Props<Payload = unknown> = DialogPrimitive.Trigger.Props<Payload>;
  export type State = DialogPrimitive.Trigger.State;
}

const Close = DialogPrimitive.Close;
namespace Close {
  export type Props = DialogPrimitive.Close.Props;
  export type State = DialogPrimitive.Close.State;
}

const Title = DialogPrimitive.Title;
namespace Title {
  export type Props = DialogPrimitive.Title.Props;
  export type State = DialogPrimitive.Title.State;
}

const Description = DialogPrimitive.Description;
namespace Description {
  export type Props = DialogPrimitive.Description.Props;
  export type State = DialogPrimitive.Description.State;
}

const Viewport = DialogPrimitive.Viewport;
namespace Viewport {
  export type Props = DialogPrimitive.Viewport.Props;
  export type State = DialogPrimitive.Viewport.State;
}

const Handle = DialogPrimitive.Handle;
type Handle<Payload> = DialogPrimitive.Handle<Payload>;
const createHandle = DialogPrimitive.createHandle;

export {
  Root,
  Trigger,
  Portal,
  Backdrop,
  Popup,
  Viewport,
  Title,
  Description,
  Close,
  Handle,
  createHandle,
  type DialogFlipDirection,
};

import type { Backdrop, Popup } from './dialog';

export type { DialogFlipDirection } from './dialog';

export * as Dialog from './dialog';
export type * from '@base-ui/react/dialog';
export type DialogBackdropProps = Backdrop.Props;
export type DialogPopupProps = Popup.Props;
